// Real A08 HTML generated by test_report_labels.py, synthetic data; no detector/camera claims.
import { createRequire } from "node:module";
import { pathToFileURL } from "node:url";
import { resolve } from "node:path";
const { chromium } = createRequire(import.meta.url)(process.env.PLAYWRIGHT_MODULE ?? "playwright");
const labels = ["Возможная речь рядом", "Видны наушники", "Лицо не совпадает с началом экзамена", "Посторонний предмет в кадре", "Второй экран или ноутбук в кадре"];
const browser = await chromium.launch({ executablePath: process.env.CHROMIUM_PATH || undefined });
try {
  const page = await browser.newPage({ viewport: { width: 1366, height: 768 } });
  const errors = [];
  page.on("pageerror", (e) => errors.push(String(e)));
  await page.goto(pathToFileURL(resolve(process.argv[2])).href);
  for (const label of labels) {
    if (await page.getByRole("heading", { level: 3, name: new RegExp(label) }).count() !== 1) throw new Error(`Missing card: ${label}`);
    if (await page.getByRole("cell", { name: label, exact: true }).count() !== 1) throw new Error(`Missing table label: ${label}`);
    console.log(`PASS real HTML: ${label}`);
  }
  if (await page.evaluate(() => document.documentElement.scrollWidth > innerWidth + 1)) throw new Error("Report horizontal overflow");
  if (errors.length) throw new Error(errors.join(" | "));
  if (process.argv[3]) await page.locator(".incident").nth(2).screenshot({ path: process.argv[3] });
  console.log("PASS report layout and no page errors");
} finally { await browser.close(); }
